import{_ as i,c as a,o as t,ae as n}from"./chunks/framework.Bw0Gm4PQ.js";const m=JSON.parse('{"title":"Reinvigorating America’s Beautiful Clean Coal Industry and Amending Executive Order 14241","description":"","frontmatter":{"title":"Reinvigorating America’s Beautiful Clean Coal Industry and Amending Executive Order 14241","sourceUrl":"https://www.whitehouse.gov/presidential-actions/2025/04/reinvigorating-americas-beautiful-clean-coal-industry-and-amending-executive-order-14241/","publishDate":"2025-04-08T17:35:09-04:00"},"headers":[],"relativePath":"executive-orders/2025-04-08-reinvigorating-americas-beautiful-clean-coal-industry-and-amending-executive-order-14241.md","filePath":"executive-orders/2025-04-08-reinvigorating-americas-beautiful-clean-coal-industry-and-amending-executive-order-14241.md"}'),r={name:"executive-orders/2025-04-08-reinvigorating-americas-beautiful-clean-coal-industry-and-amending-executive-order-14241.md"};function o(s,e,l,c,d,u){return t(),a("div",null,e[0]||(e[0]=[n('<h1 id="reinvigorating-america-s-beautiful-clean-coal-industry-and-amending-executive-order-14241" tabindex="-1">Reinvigorating America’s Beautiful Clean Coal Industry and Amending Executive Order 14241 <a class="header-anchor" href="#reinvigorating-america-s-beautiful-clean-coal-industry-and-amending-executive-order-14241" aria-label="Permalink to &quot;Reinvigorating America’s Beautiful Clean Coal Industry and Amending Executive Order 14241&quot;">​</a></h1><p>Source: <a href="https://www.whitehouse.gov/presidential-actions/2025/04/reinvigorating-americas-beautiful-clean-coal-industry-and-amending-executive-order-14241/" target="_blank" rel="noreferrer">https://www.whitehouse.gov/presidential-actions/2025/04/reinvigorating-americas-beautiful-clean-coal-industry-and-amending-executive-order-14241/</a></p><p>Published: 2025-04-08T17:35:09-04:00</p><ul><li>The Executive Order orders an increase in domestic energy production, particularly coal, to enhance economic prosperity and national security.</li><li>Emphasizes coal&#39;s abundance, cost-effectiveness, and capacity to meet electrical demand from emerging technologies.</li><li>Establishes coal as essential for national and economic security, prioritizing federal support for the domestic coal industry.</li><li>Directs the Chair of the National Energy Dominance Council (NEDC) to designate coal as a &quot;mineral,&quot; granting it benefits under relevant laws.</li><li>Requires a consolidated report from key federal secretaries within 60 days, assessing coal resources, impediments to mining, and the impact on electricity costs.</li><li>Mandates federal agencies to expedite coal leasing and prioritize coal-related activities on federal lands.</li><li>Calls for reviews and potential rescinding of regulations that discourage coal production and usage within 30 to 60 days.</li><li>Directs the Secretary of Commerce to promote export opportunities for coal and coal technologies.</li><li>Instructs a determination of coal&#39;s status as a &quot;critical material&quot; and &quot;critical mineral&quot; under existing legislation.</li><li>Requests an assessment of coal-powered infrastructure suitability for AI data centers, with findings due in 60 days.</li><li>Orders the Secretary of Energy to accelerate the development and commercialization of coal technologies and submit an action plan within 90 days.</li><li>Stipulates that the order does not affect existing legal authorities or create enforceable rights.</li></ul>',4)]))}const f=i(r,[["render",o]]);export{m as __pageData,f as default};
